x-reference.protocol:
/**
 * The volter-tunnel control-channel wire protocol — the single source of truth
 * for the messages exchanged over the control WebSocket between a client and the
 * relay. Both the client and the relay import these types; a change here is a
 * change to the contract, type-checked on both sides.
 */
import type { AccountSnapshot, CorrelationId, HeaderMap, RateWindow, UsageLevel } from './dto';

// ── client → relay ────────────────────────────────────────────────────────────

/** First frame the client sends; reserves a tunnel id and sets auth options. */
export interface RegisterMsg {
  type: 'register';
  /** Requested tunnel id; the relay generates one if omitted. */
  tunnelId?: string;
  /** Shared secret or api/login token authenticating the client. */
  secret?: string;
  /** Replace an existing live registration for this id (reconnect). */
  replace?: boolean;
  /** Whether inbound requests must pass the relay's JWT/cookie auth layer. */
  authRequired: boolean;
  /** Optional HTTP basic-auth gate applied to every inbound request. */
  basicAuth?: { user: string; pass: string };
}

/** A complete (buffered) response — used for relay-visible errors like 502. */
export interface ResponseMsg {
  type: 'response';
  reqId: CorrelationId;
  status: number;
  headers: HeaderMap;
  /** base64-encoded body. */
  body: string;
}

/** Start of a streamed response (status + headers, body follows in chunks). */
export interface ResponseStartMsg {
  type: 'response-start';
  reqId: CorrelationId;
  status: number;
  headers: HeaderMap;
}

/** One streamed response body chunk. */
export interface ResponseChunkMsg {
  type: 'response-chunk';
  reqId: CorrelationId;
  /** base64-encoded chunk. */
  data: string;
}

/** End of a streamed response. */
export interface ResponseEndMsg {
  type: 'response-end';
  reqId: CorrelationId;
}

/** The client connected to the local WebSocket and is ready to relay frames. */
export interface WsReadyMsg {
  type: 'ws-ready';
  connId: CorrelationId;
}

/** The client failed to establish/maintain the local WebSocket. */
export interface WsErrorMsg {
  type: 'ws-error';
  connId: CorrelationId;
  error: string;
}

// ── relay → client ────────────────────────────────────────────────────────────

/** Acknowledges a successful registration; carries the public URL + usage. */
export interface RegisteredMsg {
  type: 'registered';
  tunnelId: string;
  url: string;
  /** Present when the relay meters usage for this account. */
  account?: AccountSnapshot;
}

/** An inbound HTTP request to forward to the local server. */
export interface RequestMsg {
  type: 'request';
  reqId: CorrelationId;
  method: string;
  path: string;
  headers: HeaderMap;
  /** base64-encoded body, or null for bodyless methods. */
  body: string | null;
}

/** The relay asks the client to abort an in-flight request. */
export interface RequestAbortMsg {
  type: 'request-abort';
  reqId: CorrelationId;
}

/** An inbound browser WebSocket upgrade to bridge to the local server. */
export interface WsUpgradeMsg {
  type: 'ws-upgrade';
  connId: CorrelationId;
  path: string;
  headers: HeaderMap;
}

/** Account usage level changed (ok ↔ warn ↔ exceeded). */
export interface QuotaMsg {
  type: 'quota';
  level: UsageLevel;
  day: RateWindow;
  month: RateWindow;
}

/** A terminal protocol/registration error from the relay. */
export interface ErrorMsg {
  type: 'error';
  message: string;
  /** The client must not reconnect this control session without operator action. */
  fatal?: boolean;
}

// ── bidirectional (same shape both ways) ──────────────────────────────────────

/** A WebSocket data frame relayed in either direction. */
export interface WsMessageMsg {
  type: 'ws-message';
  connId: CorrelationId;
  /** base64-encoded frame payload. */
  data: string;
  binary: boolean;
}

/** A WebSocket close relayed in either direction. */
export interface WsCloseMsg {
  type: 'ws-close';
  connId: CorrelationId;
  code?: number;
  reason?: string;
}

// ── unions ────────────────────────────────────────────────────────────────────

/** Frames a client sends to the relay. */
export type ClientToRelay =
  | RegisterMsg
  | ResponseMsg
  | ResponseStartMsg
  | ResponseChunkMsg
  | ResponseEndMsg
  | WsReadyMsg
  | WsErrorMsg
  | WsMessageMsg
  | WsCloseMsg;

/** Frames the relay sends to a client. */
export type RelayToClient =
  | RegisteredMsg
  | RequestMsg
  | RequestAbortMsg
  | WsUpgradeMsg
  | QuotaMsg
  | ErrorMsg
  | WsMessageMsg
  | WsCloseMsg;

/** Any control-channel message. */
export type ControlMessage = ClientToRelay | RelayToClient;

/** Every valid `type` discriminator, the authoritative registry. */
export const MESSAGE_TYPES = [
  'register',
  'response',
  'response-start',
  'response-chunk',
  'response-end',
  'ws-ready',
  'ws-error',
  'ws-message',
  'ws-close',
  'registered',
  'request',
  'request-abort',
  'ws-upgrade',
  'quota',
  'error',
] as const;

export type MessageType = (typeof MESSAGE_TYPES)[number];

const MESSAGE_TYPE_SET: ReadonlySet<string> = new Set(MESSAGE_TYPES);

/** True if `x` is an object with a known control-message `type` discriminator. */
export function isControlMessage(x: unknown): x is ControlMessage {
  return (
    typeof x === 'object' &&
    x !== null &&
    !Array.isArray(x) &&
    typeof (x as { type?: unknown }).type === 'string' &&
    MESSAGE_TYPE_SET.has((x as { type: string }).type)
  );
}

x-reference.relay:
/**
 * TunnelDO — one Durable Object per tunnelId.
 *
 * Holds the tunnel client's control WebSocket (hibernatable) and relays inbound
 * HTTP requests and browser WebSocket connections over it, using the same wire
 * protocol defined in @volter/tunnel-core. Because there is exactly one DO per tunnelId
 * (Worker routes via idFromName(tunnelId)), the multi-tenant `clients` map a single-process relay needs collapses to "the one control socket this DO holds".
 *
 * Hibernation model: WebSockets + their serialized attachments survive eviction
 * (re-fetched via ctx.getWebSockets(tag)). In-memory correlation maps only need
 * to live for the duration of a single awaited fetch (the DO stays resident while
 * a request is in flight), so request/upgrade correlation uses instance maps.
 */
import { DurableObject } from 'cloudflare:workers';
import {
  type Env,
  type HeaderRules,
  buildResponseHeaders,
  cookieFor,
  corsHeaders,
  parseHeaderRules,
  stripAuthCookie,
  stripTokenParam,
  validateAuth,
  validateWsAuth,
} from './auth';
import { CREDIT_WEIGHTS, hashToken, parseToken, type UsageDelta } from './credits';
import { burstStep, envNum, reservationDecision } from './metering-types';
import type {
  AuthorizeResult,
  BurstState,
  DeviceCredentialResult,
  LeaseResult,
  RateSnapshot,
  Reservation,
} from './metering-types';
import { sendFrame } from './protocol';

interface CtlAttach {
  role: 'ctl';
  registered: boolean;
  /** A connector replaced after the successor was authorized. Its eventual
   * close must not settle or tear down state now owned by that successor. */
  superseded?: boolean;
  authRequired: boolean;
  tunnelId: string;
  /** Account this tunnel meters against — set at register, survives hibernation. */
  slug?: string;
  /** Credits granted per lease top-up (from the account config). */
  leaseChunk?: number;
  /** Date.now() at register — tunnel-seconds are billed from here on close. */
  openedAt?: number;
  /** Registration nonce — disambiguates this socket's account entry from a
   *  replacement's, so a superseded socket's close can't clobber the new owner. */
  regId?: string;
  /** Re-authorize inputs (so a reaped-but-live tunnel can re-register its entry). */
  legacy?: boolean;
  tokenHash?: string;
  /** Active device credential that won this reserved-id lease. Newer
   * credentials may replace it; older credentials may not evict it. */
  credentialCreatedAt?: string;
  credentialId?: string;
  /** SHA-256 of "user:pass" when the tunnel is gated by HTTP Basic Auth (#6). */
  basicAuthHash?: string;
}
interface BrowserAttach {
  role: 'browser';
  connId: string;
}

interface PendingHttp {
  resolve: (r: Response) => void;
  timer: ReturnType<typeof setTimeout>;
  request: Request;
  bootstrapCookie: string | null;
  /** RateLimit-* headers captured at request time, applied to the response. */
  rate: Record<string, string>;
}
interface Streaming {
  controller: ReadableStreamDefaultController<Uint8Array>;
  idle: ReturnType<typeof setTimeout>;
}
interface PendingUpgrade {
  resolve: () => void;
  reject: (e: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

/** One captured request for the live inspector (#5). Metadata only — no bodies
 *  or headers; persistence/replay is the paid #10. In-memory, so the buffer is
 *  lost on hibernation (fine for a live view of an actively-used tunnel). */
interface InspectEntry {
  id: string;
  t: number;
  method: string;
  path: string;
  status: number | null;
  ms: number | null;
  bytes: number | null;
}

/** A captured request stored for replay (#10). Body is base64, size-capped. */
interface Capture {
  method: string;
  path: string;
  headers: Record<string, string>;
  body: string | null;
  at: number;
}

/** Charge relayed messages (stream chunks / WS frames) in batches of this many,
 *  keeping the per-frame path cheap. Caps unmetered overshoot at one batch. */
const MSG_FLUSH_EVERY = 32;

/** Max requests retained in the live inspector ring (#5). */
const INSPECT_CAP = 50;

function b64encode(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]!);
  return btoa(s);
}
function b64decode(b64: string): Uint8Array {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}
function headersToObject(headers: Headers): Record<string, string> {
  const out: Record<string, string> = {};
  headers.forEach((v, k) => {
    out[k] = v;
  });
  return out;
}

/** Prepare visitor headers for the local origin. Never trust a visitor-supplied
 * X-Forwarded-For value: Cloudflare's edge-authenticated CF-Connecting-IP is the
 * authority. A fail-closed non-loopback sentinel prevents downstream apps from
 * mistaking a proxied request for a localhost caller when that header is absent
 * in local/self-hosted relay environments. */
function forwardedRequestHeaders(request: Request): Record<string, string> {
  const out = stripAuthCookie(headersToObject(request.headers));
  delete out['x-forwarded-for'];
  out['x-forwarded-for'] = request.headers.get('cf-connecting-ip') || '0.0.0.0';
  return out;
}

/**
 * Clamp a WebSocket close reason to 123 UTF-8 bytes (a control frame's reason is
 * capped at 125 bytes minus the 2-byte code). close() throws RangeError otherwise
 * — this guard was added after one oversized relayed reason crash-looped a relay. Drops a trailing replacement char from a severed sequence.
 */
function truncateReason(value: unknown): string {
  const s = String(value ?? '');
  const enc = new TextEncoder().encode(s);
  if (enc.length <= 123) return s;
  return new TextDecoder().decode(enc.subarray(0, 123)).replace(/�+$/, '');
}

/** Constant-time string compare for the shared secret (avoids early-exit timing). */
function safeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}

export class TunnelDO extends DurableObject<Env> {
  private pendingHttp = new Map<string, PendingHttp>();
  private streaming = new Map<string, Streaming>();
  private pendingUpgrades = new Map<string, PendingUpgrade>();

  /** Operator response-header rewrite rules (parsed once from env). */
  private _headerRules: HeaderRules | null = null;
  private get headerRules(): HeaderRules {
    return (this._headerRules ??= parseHeaderRules(this.env.RESPONSE_HEADER_RULES));
  }

  /** Per-tunnel request-rate burst limiter state (#4; in-memory, resets on
   *  hibernation — lenient, it only bounds bursts while the DO is resident). */
  private burst: BurstState = { tokens: 0, last: 0, init: false };

  /** Live request inspector ring (#5; in-memory, persisted to storage when
   *  INSPECT_REPLAY is on so it survives hibernation — #10). */
  private inspect: InspectEntry[] = [];
  private inspectByReq = new Map<string, InspectEntry>();
  /** Captured requests for replay (#10), keyed by reqId. Persisted when enabled. */
  private captures = new Map<string, Capture>();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    // Only touch storage when replay/persistence is on — otherwise the inspector
    // is purely in-memory (#5) and a cold DO does no extra reads.
    if (env.INSPECT_REPLAY === 'true' || env.INSPECT_REPLAY === '1') {
      ctx.blockConcurrencyWhile(async () => {
        this.inspect = (await ctx.storage.get<InspectEntry[]>('inspect')) ?? [];
        const caps = (await ctx.storage.get<Record<string, Capture>>('captures')) ?? {};
        this.captures = new Map(Object.entries(caps));
      });
    }
  }

  private get replayEnabled(): boolean {
    return this.env.INSPECT_REPLAY === 'true' || this.env.INSPECT_REPLAY === '1';
  }

  /** Record a request as it starts; trims the ring to its cap. */
  private pushInspect(reqId: string, method: string, path: string): void {
    const e: InspectEntry = { id: reqId, t: Date.now(), method, path, status: null, ms: null, bytes: null };
    this.inspect.push(e);
    const cap = envNum(this.env.INSPECT_MAX, INSPECT_CAP);
    while (this.inspect.length > cap) this.inspect.shift();
    this.inspectByReq.set(reqId, e);
  }
  /** Fill in a request's outcome (status, latency, response size) on completion. */
  private finishInspect(reqId: string, status: number, bytes: number | null): void {
    const e = this.inspectByReq.get(reqId);
    if (!e) return;
    e.status = status;
    e.ms = Date.now() - e.t;
    e.bytes = bytes;
    this.inspectByReq.delete(reqId);
    if (this.replayEnabled) void this.ctx.storage.put('inspect', this.inspect).catch(() => {});
  }

  /** Persist a captured request for later replay (#10), trimming to INSPECT_MAX. */
  private async captureForReplay(
    id: string,
    method: string,
    path: string,
    headers: Record<string, string>,
    bodyBytes: Uint8Array | null
  ): Promise<void> {
    const maxBody = envNum(this.env.INSPECT_BODY_MAX, 65536);
    const body = bodyBytes?.length && bodyBytes.length <= maxBody ? b64encode(bodyBytes) : null;
    this.captures.set(id, { method, path, headers, body, at: Date.now() });
    const cap = envNum(this.env.INSPECT_MAX, INSPECT_CAP);
    while (this.captures.size > cap) {
      const oldest = this.captures.keys().next().value;
      if (oldest === undefined) break;
      this.captures.delete(oldest);
    }
    await this.ctx.storage.put('captures', Object.fromEntries(this.captures));
  }

  // ── metering state (ephemeral; safe to lose on hibernation) ────────────────
  /** Credits leased from the account but not yet spent. */
  private budget = 0;
  /** Credits spent since the last lease/close flush to the account. */
  private consumedSinceCommit = 0;
  /** Raw usage (for dashboards) accumulated since the last flush. */
  private rawSinceFlush: UsageDelta = { requests: 0, wsUpgrades: 0, bytes: 0, seconds: 0 };
  /** Serializes budget mutations so concurrent requests don't double-lease. */
  private budgetChain: Promise<unknown> = Promise.resolve();
  /** Latest limit snapshot from the account (for RateLimit headers + quota push). */
  private rate: RateSnapshot | null = null;
  /** Last quota level pushed to the client — only re-push on change. */
  private lastQuotaLevel: string | null = null;
  /** Relayed DO messages (response chunks + WS frames) not yet charged. Flushed
   *  in batches so the per-frame path stays cheap; bounds unmetered overshoot. */
  private msgsSinceFlush = 0;

  private accountStub(slug?: string): DurableObjectStub | null {
    const s = slug ?? this.ctlAttach()?.slug;
    if (!s) return null;
    return this.env.ACCOUNTS.get(this.env.ACCOUNTS.idFromName(s));
  }

  /** RPC to the account DO. `slug` is required at register (before the slug is in
   *  the attachment); afterwards it's read from the attachment. */
  private async accountRpc<T>(path: string, payload: Record<string, unknown>, slug?: string): Promise<T | null> {
    const stub = this.accountStub(slug ?? (payload.slug as string | undefined));
    if (!stub) return null;
    try {
      const res = await stub.fetch(`https://account${path}`, {
        method: 'POST',
        body: JSON.stringify(payload),
      });
      return (await res.json()) as T;
    } catch {
      return null;
    }
  }

  private async registryRpc<T>(path: string, payload: Record<string, unknown>): Promise<T | null> {
    try {
      const stub = this.env.REGISTRY.get(this.env.REGISTRY.idFromName('registry'));
      const res = await stub.fetch(`https://registry${path}`, {
        method: 'POST',
        body: JSON.stringify(payload),
      });
      return (await res.json()) as T;
    } catch {
      return null;
    }
  }

  private takeRaw(): UsageDelta {
    const r = this.rawSinceFlush;
    this.rawSinceFlush = { requests: 0, wsUpgrades: 0, bytes: 0, seconds: 0 };
    return r;
  }

  /** Record the latest account snapshot and, on a level change, push a `quota`
   *  frame to the client so the CLI/gateway can warn before the hard cutoff. */
  private applyRate(rate: RateSnapshot | undefined): void {
    if (!rate) return;
    this.rate = rate;
    if (rate.level !== this.lastQuotaLevel) {
      this.lastQuotaLevel = rate.level;
      const ctl = this.ctl();
      if (ctl) {
        try {
          sendFrame(ctl, { type: 'quota', level: rate.level, day: rate.day, month: rate.month });
        } catch {
          /* control gone */
        }
      }
    }
  }

  /** IETF RateLimit-* headers (draft-ietf-httpapi-ratelimit-headers) for the
   *  binding daily window. `reset` is seconds until refill. */
  private rateHeaders(): Record<string, string> {
    if (!this.rate) return {};
    const nowSec = Math.floor(Date.now() / 1000);
    return {
      'ratelimit-limit': String(this.rate.day.limit),
      'ratelimit-remaining': String(Math.max(0, this.rate.day.remaining)),
      'ratelimit-reset': String(Math.max(1, this.rate.day.reset - nowSec)),
    };
  }

  /** Seconds until the binding window refills — for Retry-After on a 429. */
  private retryAfterSeconds(): number {
    if (!this.rate) return 60;
    const nowSec = Math.floor(Date.now() / 1000);
    const dayOut = this.rate.day.remaining <= 0;
    const reset = dayOut ? this.rate.day.reset : this.rate.month.reset;
    return Math.max(1, reset - nowSec);
  }

  /**
   * Pre-authorize `cost` credits before relaying. Spends from the local lease;
   * tops the lease up from the account when short. Returns false (→ 429) when the
   * account has no budget left — the hard cutoff that bounds spend. Fail-closed:
   * an unreachable account yields no grant, so traffic stops rather than runs free.
   */
  private ensureBudget(cost: number): Promise<boolean> {
    const run = this.budgetChain.then(async () => {
      if (this.budget >= cost) {
        this.budget -= cost;
        this.consumedSinceCommit += cost;
        return true;
      }
      const attach = this.ctlAttach();
      const tunnelId = attach?.tunnelId ?? '';
      const want = Math.max(attach?.leaseChunk ?? 50, cost);
      let res = await this.accountRpc<LeaseResult>('/lease', {
        tunnelId,
        regId: attach?.regId,
        want,
        commit: this.consumedSinceCommit,
        raw: this.takeRaw(),
      });
      this.consumedSinceCommit = 0;
      // The account reaped our (idle) entry → re-register it and retry once so a
      // still-connected tunnel self-heals instead of getting wedged at 0 budget.
      if (res?.notOpen && (await this.reauthorize())) {
        res = await this.accountRpc<LeaseResult>('/lease', {
          tunnelId,
          regId: this.ctlAttach()?.regId,
          want,
          commit: 0,
          raw: this.takeRaw(),
        });
      }
      this.applyRate(res?.rate);
      this.budget += res?.grant ?? 0;
      if (this.budget >= cost) {
        this.budget -= cost;
        this.consumedSinceCommit += cost;
        return true;
      }
      return false;
    });
    this.budgetChain = run.catch(() => {});
    return run;
  }

  /** Re-authorize this tunnel's account entry after a reap. Runs inside the budget
   *  chain (callers already hold it). True if the account re-accepted the tunnel. */
  private async reauthorize(): Promise<boolean> {
    const a = this.ctlAttach();
    if (!a?.slug || !a.regId) return false;
    const auth = await this.accountRpc<AuthorizeResult>('/authorize', {
      slug: a.slug,
      legacy: a.legacy,
      tokenHash: a.tokenHash,
      tunnelId: a.tunnelId,
      regId: a.regId,
    });
    return !!auth?.ok;
  }

  /** Charge one relayed-message op. Fast path: spend from the locally-held lease
   *  synchronously (no await, atomic in the single-threaded DO). Slow path (local
   *  budget exhausted): await a top-up from the account. Returns false when the
   *  account is out of budget — the caller must then cut the traffic off. This is
   *  the synchronous gate the floodable browser-frame path needs so it can never
   *  relay unmetered while an async charge is in flight. */
  private async chargeMessage(): Promise<boolean> {
    const cost = CREDIT_WEIGHTS.message;
    if (this.budget >= cost) {
      this.budget -= cost;
      this.consumedSinceCommit += cost;
      return true;
    }
    return this.ensureBudget(cost);
  }

  /** Charge the batch of relayed CONTROL messages accrued since the last flush. On
   *  exhaustion, cut the chatty traffic off by closing the browser sockets
   *  (the control socket stays so the client can re-auth after the reset). */
  private async flushMessages(): Promise<void> {
    const n = this.msgsSinceFlush;
    if (n <= 0) return;
    this.msgsSinceFlush = 0;
    const ok = await this.ensureBudget(n * CREDIT_WEIGHTS.message);
    if (!ok) {
      this.applyRate(this.rate ?? undefined); // ensure an 'exceeded' quota push
      for (const b of this.ctx.getWebSockets('browser')) {
        try {
          (b as WebSocket).close(1011, 'Account quota exceeded');
        } catch {
          /* already gone */
        }
      }
    }
  }

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const upgrade = request.headers.get('Upgrade');

    // Internal admin: revoke this tunnelId's reservation (#3). Reached only via a
    // DO-to-DO call from the RegistryDO after it has authenticated root; gated by
    // the root token so a browser hitting this path on the tunnel host can't.
    if (url.pathname === '/__internal/revoke-reservation') {
      const bearer = (request.headers.get('authorization') || '').replace(/^Bearer /, '');
      if (!this.env.ROOT_TOKEN || !safeEqual(bearer, this.env.ROOT_TOKEN)) {
        return new Response('forbidden', { status: 403 });
      }
      return this.revokeReservation(request.headers.get('x-volter-expected-owner'));
    }

    // Control channel: the tunnel client connects to /ws?id=<tunnelId>.
    if (url.pathname === '/ws') {
      if (upgrade !== 'websocket') return new Response('expected websocket', { status: 426 });
      return this.acceptControl(url);
    }

    // Browser-side WebSocket upgrade on a tunnel subdomain.
    if (upgrade === 'websocket') return this.handleBrowserWsUpgrade(request, url);

    // Plain HTTP data request.
    return this.handleHttpRequest(request, url);
  }

  /** Revoke this tunnelId's reservation (#3): release the slot on the owner's
   *  account, clear the persistent record, and disconnect any live client. */
  private async revokeReservation(expectedOwner: string | null): Promise<Response> {
    const res = await this.ctx.storage.get<Reservation>('reservation');
    if (expectedOwner && res?.ownerSlug !== expectedOwner) {
      return Response.json({ ok: false, error: 'reservation owner changed' }, { status: 409 });
    }
    if (res?.tunnelId) {
      await this.accountRpc('/release-id', { tunnelId: res.tunnelId }, res.ownerSlug);
    }
    await this.ctx.storage.delete('reservation');
    for (const w of this.ctx.getWebSockets('ctl')) {
      try {
        (w as WebSocket).close(4010, 'Reservation revoked');
      } catch {
        /* already gone */
      }
    }
    return Response.json({ ok: true, revoked: !!res, slug: res?.ownerSlug ?? null });
  }

  // ── control socket helpers ────────────────────────────────────────────────
  private ctl(): WebSocket | null {
    const arr = this.ctx.getWebSockets('ctl');
    const registered = arr.find((ws) => (ws.deserializeAttachment() as CtlAttach | null)?.registered);
    return (registered ?? arr[0] ?? null) as WebSocket | null;
  }
  private ctlAttach(): CtlAttach | null {
    const ws = this.ctl();
    return ws ? (ws.deserializeAttachment() as CtlAttach) : null;
  }

  private acceptControl(url: URL): Response {
    // The Worker routed us via idFromName(?id=), so ?id= is the authoritative
    // tunnelId for this DO — capture it so the registered URL always matches the
    // subdomain the browser actually reaches (don't trust msg.tunnelId blindly).
    const id = url.searchParams.get('id') || '';
    const { 0: client, 1: server } = new WebSocketPair();
    const attach: CtlAttach = { role: 'ctl', registered: false, authRequired: true, tunnelId: id };
    server.serializeAttachment(attach);
    this.ctx.acceptWebSocket(server, ['ctl']);
    return new Response(null, { status: 101, webSocket: client });
  }

  /** Validate an Authorization: Basic header against the stored "user:pass" hash
   *  (#6). Constant-time on the hash; returns false on any missing/malformed input. */
  private async checkBasicAuth(request: Request, expectedHash: string): Promise<boolean> {
    const h = request.headers.get('authorization');
    if (!h || !h.startsWith('Basic ')) return false;
    let decoded: string;
    try {
      decoded = atob(h.slice(6).trim());
    } catch {
      return false;
    }
    return safeEqual(await hashToken(decoded), expectedHash);
  }

  /** Owner-only gate for the inspector/replay endpoints (#sec): the caller must
   *  present the tunnel's own secret (api token or, for legacy, TUNNEL_SECRET).
   *  This keeps request metadata private even on a public (authRequired=false)
   *  tunnel — without forcing JWT auth on visitors, which would break sharing. */
  private async inspectorAuthorized(request: Request, attach: CtlAttach): Promise<boolean> {
    const bearer = (request.headers.get('authorization') || '').replace(/^Bearer /, '');
    if (!bearer) return false;
    if (attach.tokenHash) return safeEqual(await hashToken(bearer), attach.tokenHash);
    if (attach.legacy && this.env.TUNNEL_SECRET) return safeEqual(bearer, this.env.TUNNEL_SECRET);
    return false;
  }

  // ── inbound HTTP ──────────────────────────────────────────────────────────
  // `isReplay` (#10) marks an internally re-issued capture: it has already been
  // authorized via the auth-gated /__volter_replay endpoint, so it skips the
  // burst/auth/endpoint preamble and goes straight to meter + forward.
  private async handleHttpRequest(request: Request, url: URL, isReplay = false): Promise<Response> {
    // Answer CORS preflight BEFORE the connectivity check (answer it early) so
    // a momentarily-down tunnel doesn't surface a CORS error to the browser.
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: corsHeaders(request) });
    }
    const ctl = this.ctl();
    const attach = this.ctlAttach();
    if (!ctl || !attach?.registered) {
      return new Response('Tunnel not connected', { status: 502, headers: corsHeaders(request) });
    }

    // Per-tunnel request-rate burst limit (#4) — cheap flood guard ahead of auth
    // and forwarding. The daily/monthly credit caps remain the primary limit.
    const rps = envNum(this.env.BURST_RPS, 0);
    if (!isReplay && rps > 0) {
      const retry = burstStep(this.burst, Date.now(), rps, envNum(this.env.BURST_SIZE, rps * 2));
      if (retry > 0) {
        return new Response('Too Many Requests', {
          status: 429,
          headers: { ...corsHeaders(request), 'retry-after': String(retry) },
        });
      }
    }

    // Basic-auth gate (#6): if the tunnel was registered with credentials, every
    // inbound request must present a matching Authorization: Basic header before
    // anything is served or forwarded (independent of the JWT layer below).
    if (!isReplay && attach.basicAuthHash && !(await this.checkBasicAuth(request, attach.basicAuthHash))) {
      return new Response('Authentication required', {
        status: 401,
        headers: {
          ...corsHeaders(request),
          'www-authenticate': 'Basic realm="volter-tunnel"',
        },
      });
    }

    let bootstrapCookie: string | null = null;
    if (!isReplay && attach.authRequired && this.env.JWT_SECRET) {
      const auth = await validateAuth(request, url, this.env.JWT_SECRET, {
        tunnelId: attach.tunnelId,
        requireTid: this.env.REQUIRE_TID === 'true',
      });
      if (!auth) {
        return Response.json({ error: 'Authentication required' }, { status: 401, headers: corsHeaders(request) });
      }
      if (auth.source === 'query') {
        // Scope the cookie to THIS tunnel so a token bootstrapped on one tunnel's
        // subdomain isn't sent to (and rejected by) another open tunnel.
        bootstrapCookie = cookieFor(auth.token, `${attach.tunnelId}.${this.env.TUNNEL_DOMAIN}`);
      }
    }

    // Live request inspector (#5): recent request metadata, served on a reserved
    // path (never forwarded) and gated by the same auth as the tunnel above.
    if (!isReplay && url.pathname === '/__volter_inspect') {
      if (!(await this.inspectorAuthorized(request, attach))) {
        return new Response('Unauthorized', { status: 401, headers: corsHeaders(request) });
      }
      return Response.json(
        { tunnelId: attach.tunnelId, entries: this.inspect, replay: this.replayEnabled },
        { headers: corsHeaders(request) }
      );
    }

    // Replay a captured request (#10): re-issue it through the tunnel. Owner-only
    // (tunnel secret); only available when INSPECT_REPLAY is enabled.
    if (!isReplay && url.pathname === '/__volter_replay' && request.method === 'POST') {
      if (!this.replayEnabled) {
        return Response.json({ error: 'replay not enabled' }, { status: 404, headers: corsHeaders(request) });
      }
      if (!(await this.inspectorAuthorized(request, attach))) {
        return new Response('Unauthorized', { status: 401, headers: corsHeaders(request) });
      }
      const b = (await request.json().catch(() => ({}))) as { id?: string };
      const cap = b.id ? this.captures.get(b.id) : undefined;
      if (!cap) {
        return Response.json({ error: 'no such captured request' }, { status: 404, headers: corsHeaders(request) });
      }
      const replayUrl = new URL(`https://${attach.tunnelId}.${this.env.TUNNEL_DOMAIN}${cap.path}`);
      const synth = new Request(replayUrl.toString(), {
        method: cap.method,
        headers: cap.headers,
        body: cap.body ? b64decode(cap.body) : undefined,
      });
      return this.handleHttpRequest(synth, replayUrl, true);
    }

    const forwardPath = stripTokenParam(url.pathname + url.search);
    const forwardHeaders = forwardedRequestHeaders(request);
    const hasBody = request.method !== 'GET' && request.method !== 'HEAD';
    const bodyBytes = hasBody ? new Uint8Array(await request.arrayBuffer()) : null;

    // A DO WebSocket frame is capped at 1 MiB and base64 inflates ~33%; the whole
    // body goes in one `request` frame. Reject oversized bodies fast with 413
    // instead of letting ctl.send throw and the request hang to the 30s timeout.
    if (bodyBytes && bodyBytes.length > 750_000) {
      return new Response('Request body too large to tunnel (limit ~750KB)', {
        status: 413,
        headers: corsHeaders(request),
      });
    }

    // Meter + hard-cutoff: a request only relays if the account has budget.
    this.rawSinceFlush.requests = (this.rawSinceFlush.requests ?? 0) + 1;
    this.rawSinceFlush.bytes = (this.rawSinceFlush.bytes ?? 0) + (bodyBytes?.length ?? 0);
    if (!(await this.ensureBudget(CREDIT_WEIGHTS.request))) {
      const retry = this.retryAfterSeconds();
      const scope = this.rate && this.rate.day.remaining <= 0 ? 'day' : 'month';
      return Response.json(
        { error: 'quota_exceeded', scope, retryAfter: retry },
        {
          status: 429,
          headers: {
            ...corsHeaders(request),
            ...this.rateHeaders(),
            'retry-after': String(retry),
          },
        }
      );
    }
    const rateHeaders = this.rateHeaders();

    const reqId = crypto.randomUUID();
    this.pushInspect(reqId, request.method, url.pathname);
    if (!isReplay && this.replayEnabled) {
      await this.captureForReplay(reqId, request.method, forwardPath, forwardHeaders, bodyBytes);
    }
    return await new Promise<Response>((resolve) => {
      const timer = setTimeout(() => {
        this.pendingHttp.delete(reqId);
        this.streaming.delete(reqId);
        this.finishInspect(reqId, 504, null);
        resolve(new Response('Tunnel timeout', { status: 504, headers: corsHeaders(request) }));
      }, 30000);
      this.pendingHttp.set(reqId, { resolve, timer, request, bootstrapCookie, rate: rateHeaders });
      try {
        sendFrame(ctl, {
          type: 'request',
          reqId,
          method: request.method,
          path: forwardPath,
          headers: forwardHeaders,
          body: bodyBytes?.length ? b64encode(bodyBytes) : null,
        });
      } catch {
        clearTimeout(timer);
        this.pendingHttp.delete(reqId);
        resolve(new Response('Tunnel send failed', { status: 502, headers: corsHeaders(request) }));
      }
    });
  }

  // ── inbound browser WebSocket ─────────────────────────────────────────────
  private async handleBrowserWsUpgrade(request: Request, url: URL): Promise<Response> {
    const ctl = this.ctl();
    const attach = this.ctlAttach();
    if (!ctl || !attach?.registered) return new Response('Tunnel not connected', { status: 502 });

    if (attach.authRequired && this.env.JWT_SECRET) {
      const okWs = await validateWsAuth(request, url, this.env.JWT_SECRET, {
        tunnelId: attach.tunnelId,
        requireTid: this.env.REQUIRE_TID === 'true',
      });
      if (!okWs) {
        return new Response('Unauthorized', { status: 401 });
      }
    }

    // Meter + hard-cutoff (one charge per upgrade; relayed frames are not priced).
    this.rawSinceFlush.wsUpgrades = (this.rawSinceFlush.wsUpgrades ?? 0) + 1;
    if (!(await this.ensureBudget(CREDIT_WEIGHTS.wsUpgrade))) {
      return new Response('Account quota exceeded', {
        status: 429,
        headers: { ...this.rateHeaders(), 'retry-after': String(this.retryAfterSeconds()) },
      });
    }

    const connId = crypto.randomUUID();
    const { 0: client, 1: server } = new WebSocketPair();
    server.serializeAttachment({ role: 'browser', connId } satisfies BrowserAttach);
    this.ctx.acceptWebSocket(server, ['browser', `c:${connId}`]);

    const cleanPath = stripTokenParam(url.pathname + url.search);
    const forwardHeaders = forwardedRequestHeaders(request);

    // Await ws-ready BEFORE returning 101 — so the browser's socket only opens
    // once the local end is connected. This removes the message-buffering dance a single-process relay needs (it can't delay its upgrade).
    const ready = new Promise<void>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pendingUpgrades.delete(connId);
        reject(new Error('ws-upgrade timeout'));
      }, 15000);
      this.pendingUpgrades.set(connId, { resolve, reject, timer });
    });
    sendFrame(ctl, { type: 'ws-upgrade', connId, path: cleanPath, headers: forwardHeaders });
    try {
      await ready;
    } catch {
      try {
        server.close(1011, 'tunnel timeout');
      } catch {
        /* already gone */
      }
      return new Response('tunnel timeout', { status: 504 });
    }
    return new Response(null, { status: 101, webSocket: client });
  }

  // ── hibernation handlers ──────────────────────────────────────────────────
  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
    const attach = ws.deserializeAttachment() as CtlAttach | BrowserAttach | null;

    // Raw browser frame → the untrusted, floodable direction. Meter it
    // SYNCHRONOUSLY (gate per frame on locally-held budget; only await a top-up
    // when exhausted) so an over-quota flood is cut off (1011) within a bounded
    // overshoot instead of being relayed unmetered while an async charge lands.
    if (attach?.role === 'browser') {
      const ctl = this.ctl();
      if (!ctl) return;
      if (!(await this.chargeMessage())) {
        try {
          ws.close(1011, 'Account quota exceeded');
        } catch {
          /* already gone */
        }
        return;
      }
      const binary = typeof data !== 'string';
      const bytes = binary ? new Uint8Array(data as ArrayBuffer) : new TextEncoder().encode(data as string);
      // A DO WS frame is capped at 1 MiB and base64 inflates ~33%; an oversized
      // browser frame would throw on ctl.send and escape the hibernation handler.
      if (bytes.length > 750_000) {
        try {
          ws.close(1009, 'frame too large to tunnel');
        } catch {
          /* already gone */
        }
        return;
      }
      try {
        sendFrame(ctl, { type: 'ws-message', connId: attach.connId, data: b64encode(bytes), binary });
      } catch {
        try {
          ws.close(1011, 'relay error');
        } catch {
          /* already gone */
        }
      }
      return;
    }

    let msg: Record<string, unknown>;
    try {
      msg = JSON.parse(typeof data === 'string' ? data : new TextDecoder().decode(data));
    } catch {
      return;
    }
    // An accepted socket may send only register until it becomes the owner. A
    // superseded connector can have already-queued frames when its close lands;
    // ignore them instead of billing or dispatching them as successor traffic.
    if ((!attach?.registered || attach.superseded) && msg.type !== 'register') return;

    // Control-channel message (responses, chunks, ws relays from the tunnel
    // client) → count for batch metering (fire-and-forget, so the lease round-trip
    // never convoys response delivery under concurrency), then dispatch.
    this.msgsSinceFlush++;
    if (this.msgsSinceFlush >= MSG_FLUSH_EVERY) void this.flushMessages().catch(() => {});
    await this.onControlMessage(ws, msg);
  }

  async webSocketClose(ws: WebSocket): Promise<void> {
    const attach = ws.deserializeAttachment() as CtlAttach | BrowserAttach | null;
    if (attach?.role === 'browser') {
      const ctl = this.ctl();
      if (ctl) {
        try {
          sendFrame(ctl, { type: 'ws-close', connId: attach.connId });
        } catch {
          /* control gone */
        }
      }
      return;
    }
    // Replacement transfers the account lease and the TunnelDO's local metering
    // state to the successor. The superseded socket's delayed close is therefore
    // deliberately inert: settling or disconnecting here would clobber traffic
    // already owned by the new registration.
    if (attach?.role === 'ctl' && (!attach.registered || attach.superseded)) return;

    // Settle metering: commit unflushed usage + tunnel-seconds and return any
    // unconsumed lease to the account (recovers budget stranded by hibernation).
    if (attach?.slug) {
      // Fold any unflushed relayed-message ops into the final settlement.
      this.consumedSinceCommit += this.msgsSinceFlush * CREDIT_WEIGHTS.message;
      this.msgsSinceFlush = 0;
      const seconds = attach.openedAt ? Math.max(0, (Date.now() - attach.openedAt) / 1000) : 0;
      await this.accountRpc(
        '/close',
        {
          slug: attach.slug,
          tunnelId: attach.tunnelId,
          regId: attach.regId,
          consumed: this.consumedSinceCommit,
          seconds,
          raw: this.takeRaw(),
        },
        attach.slug
      );
      this.consumedSinceCommit = 0;
      this.budget = 0;

      // Idle clock starts now: stamp lastSeenAt at disconnect so the reclaim TTL
      // counts from when the owner went away, not from when it first connected
      // (DECISIONS D5). Only the current owner may move its own clock.
      const res = await this.ctx.storage.get<Reservation>('reservation');
      if (res && res.ownerSlug === attach.slug) {
        await this.ctx.storage.put('reservation', {
          ...res,
          lastSeenAt: Date.now(),
        } satisfies Reservation);
      }
    }

    this.disconnectTraffic('Tunnel disconnected');
  }

  /** Tear down traffic bound to the current connector. Replacement cannot keep
   * in-flight correlations because their responses belong to the old socket. */
  private disconnectTraffic(reason: string): void {
    for (const b of this.ctx.getWebSockets('browser')) {
      try {
        (b as WebSocket).close(1001, reason);
      } catch {
        /* ignore */
      }
    }
    for (const [rid, p] of this.pendingHttp) {
      clearTimeout(p.timer);
      this.finishInspect(rid, 502, null);
      try {
        p.resolve(new Response(reason, { status: 502 }));
      } catch {
        /* already resolved */
      }
    }
    this.pendingHttp.clear();
    for (const [, s] of this.streaming) {
      clearTimeout(s.idle);
      try {
        s.controller.error(new Error(reason));
      } catch {
        /* already closed */
      }
    }
    this.streaming.clear();
    for (const [, p] of this.pendingUpgrades) {
      clearTimeout(p.timer);
      p.reject(new Error(reason));
    }
    this.pendingUpgrades.clear();
  }

  /** Idle watchdog for a streaming response — if the client stalls without sending
   *  response-end, error the stream and tell the client to abort. Reset per chunk. */
  private armStreamIdle(reqId: string): ReturnType<typeof setTimeout> {
    return setTimeout(() => {
      const s = this.streaming.get(reqId);
      if (!s) return;
      this.streaming.delete(reqId);
      try {
        s.controller.error(new Error('stream idle timeout'));
      } catch {
        /* already closed */
      }
      const ctl = this.ctl();
      if (ctl) {
        try {
          sendFrame(ctl, { type: 'request-abort', reqId });
        } catch {
          /* control gone */
        }
      }
    }, 120000);
  }

  async webSocketError(ws: WebSocket): Promise<void> {
    await this.webSocketClose(ws);
  }

  // ── control protocol ──────────────────────────────────────────────────────
  private async onControlMessage(ws: WebSocket, msg: Record<string, unknown>): Promise<void> {
    const type = msg.type as string;

    if (type === 'register') {
      // Resolve the metering account from the presented secret. An api token
      // (`vta_<slug>_…`) names + proves its account; the legacy shared
      // TUNNEL_SECRET maps to the built-in internal account for back-compat.
      // FAIL CLOSED: when TUNNEL_SECRET is unset there is no legacy path at all
      // (an api token is required) — an unset secret must never become an open
      // relay that bills the internal account for anyone.
      const secret = String(msg.secret ?? '');
      const internal = this.env.INTERNAL_ACCOUNT || 'volter-internal';
      const parsed = parseToken(secret);
      let slug: string;
      let legacy = false;
      let tokenHash: string | undefined;
      if (parsed?.kind === 'api') {
        slug = parsed.slug!;
        tokenHash = await hashToken(secret);
      } else if (this.env.TUNNEL_SECRET && safeEqual(secret, this.env.TUNNEL_SECRET)) {
        slug = internal;
        legacy = true;
      } else {
        sendFrame(ws, { type: 'error', message: 'Invalid tunnel secret' });
        ws.close(4003, 'Invalid tunnel secret');
        return;
      }

      // ── reserved-id ownership: lazy reclaim-on-contention (DECISIONS D5) ──────
      // This DO *is* the tunnelId, so a single 'reservation' record is its owner.
      // A different account may take a reserved id only once the current owner has
      // been idle past RESERVATION_IDLE_TTL_DAYS; while the owner is active a
      // foreign claim is refused so the id stays stable. lastSeenAt is refreshed
      // on (re)register (below, after authorize) and on disconnect.
      const ttlMs = envNum(this.env.RESERVATION_IDLE_TTL_DAYS, 60) * 86_400_000;
      const reservation = await this.ctx.storage.get<Reservation>('reservation');
      const verdict = reservationDecision(reservation, slug, Date.now(), ttlMs);
      if (verdict === 'reject') {
        sendFrame(ws, {
          type: 'error',
          message: `Tunnel ID '${String(msg.tunnelId ?? '')}' is reserved by another account.`,
        });
        ws.close(4002, 'Tunnel ID reserved');
        return;
      }

      const credential = legacy
        ? undefined
        : await this.registryRpc<DeviceCredentialResult>('/resolve-device-credential', { slug, tokenHash });
      if (!legacy && credential?.ok !== true) {
        sendFrame(ws, { type: 'error', fatal: true, message: 'Tunnel rejected: credential is invalid or revoked.' });
        ws.close(4003, 'Invalid tunnel secret');
        return;
      }

      const others = this.ctx
        .getWebSockets('ctl')
        .filter((w) => w !== ws && (w.deserializeAttachment() as CtlAttach | null)?.registered);
      if (others.length) {
        if (msg.replace) {
          const incomingRank = credential?.ok === true ? `${credential.createdAt}\u0000${credential.id}` : undefined;
          const incomingCredentialId = credential?.ok === true ? credential.id : undefined;
          let newerOwner: WebSocket | undefined;
          if (incomingRank !== undefined) {
            for (const candidate of others) {
              const attached = candidate.deserializeAttachment() as CtlAttach | null;
              if (
                attached?.credentialId === undefined ||
                attached.credentialCreatedAt === undefined ||
                attached.credentialId === incomingCredentialId ||
                `${attached.credentialCreatedAt}\u0000${attached.credentialId}` <= incomingRank
              )
                continue;
              const ownerCredential = await this.registryRpc<DeviceCredentialResult>('/resolve-device-credential', {
                slug,
                credentialId: attached.credentialId,
              });
              if (ownerCredential?.ok === true) {
                newerOwner = candidate as WebSocket;
                break;
              }
            }
          }
          if (newerOwner !== undefined) {
            sendFrame(ws, {
              type: 'error',
              fatal: true,
              message: `Tunnel ID '${String(msg.tunnelId ?? '')}' is active on a newer authenticated device. Stop that connector or revoke its device token before taking over.`,
            });
            ws.close(4002, 'Newer device owns tunnel');
            return;
          }
        } else {
          sendFrame(ws, {
            type: 'error',
            message: `Tunnel ID '${msg.tunnelId}' is already in use by another client. Pass { replace: true } to take over.`,
          });
          ws.close(4002, 'Tunnel ID already in use');
          return;
        }
      }

      // Prefer the ?id= captured at accept (authoritative — it's how the Worker
      // routed to this DO); fall back to msg.tunnelId, then a random id.
      const existing = ws.deserializeAttachment() as CtlAttach | null;
      const tunnelId = existing?.tunnelId || (msg.tunnelId as string) || crypto.randomUUID().slice(0, 8);

      // Unique registration nonce — lets the account tell this socket's ledger
      // entry apart from a later replacement's (fixes the replace race).
      const regId = crypto.randomUUID();
      const authRequired = msg.authRequired !== false;
      const ba = msg.basicAuth as { user?: string; pass?: string } | undefined;
      const basicAuthHash = ba?.user && ba.pass ? await hashToken(`${ba.user}:${ba.pass}`) : undefined;
      let openedAt = Date.now();
      for (const old of others) {
        const oldAttach = old.deserializeAttachment() as CtlAttach;
        if (oldAttach.openedAt !== undefined) openedAt = Math.min(openedAt, oldAttach.openedAt);
      }

      // Authorize against the account: valid token, active, under the concurrent
      // cap, and with budget remaining. A rejection closes the control socket.
      const auth = await this.accountRpc<AuthorizeResult>('/authorize', {
        slug,
        legacy,
        tokenHash,
        tunnelId,
        regId,
      });
      if (!auth || !auth.ok) {
        const reason = auth?.reason ?? 'account unavailable';
        const code = reason === 'badToken' ? 4003 : 4029;
        const message =
          reason === 'reservationCap'
            ? `Tunnel rejected: reservation capacity ${auth?.reservedTunnels?.length ?? 0}/${auth?.reservedMax ?? 0}. Reserved ids: ${auth?.reservedTunnels?.join(', ') || 'none'}. Run "volter-tunnel reservations" to inspect or "volter-tunnel release <id>" to free one.`
            : reason === 'badToken'
              ? 'Tunnel rejected: credential is invalid or revoked. On an owner-authenticated device, run "volter-tunnel tokens" and restore this host token, or sign in again on the host.'
              : `Tunnel rejected: ${reason}`;
        sendFrame(ws, { type: 'error', message });
        ws.close(code, reason);
        return;
      }

      // The account now recognizes regId as the owner. Transfer the live relay
      // state before the next await: mark predecessors inert first, fail their
      // in-flight traffic, then publish the successor as registered. Visitors
      // therefore cannot observe the account's new regId while ctl() still
      // selects an old registration.
      if (others.length) {
        for (const old of others) {
          const oldAttach = old.deserializeAttachment() as CtlAttach;
          old.serializeAttachment({ ...oldAttach, registered: false, superseded: true } satisfies CtlAttach);
        }
        this.disconnectTraffic('Tunnel replaced');
        for (const old of others) (old as WebSocket).close(4001, 'Replaced by new client');
      }
      ws.serializeAttachment({
        role: 'ctl',
        registered: true,
        authRequired,
        tunnelId,
        slug,
        leaseChunk: auth.leaseChunk ?? 50,
        openedAt,
        regId,
        legacy,
        tokenHash,
        ...(credential?.ok === true ? { credentialCreatedAt: credential.createdAt, credentialId: credential.id } : {}),
        basicAuthHash,
      } satisfies CtlAttach);

      // Account is authorized → claim/refresh/reclaim this tunnelId for it and
      // (re)start the idle clock. Same write for all three verdicts (the only
      // rejected case already returned above).
      await this.ctx.storage.put('reservation', {
        ownerSlug: slug,
        lastSeenAt: Date.now(),
        tunnelId,
      } satisfies Reservation);

      // Reclaimed from another account past its idle TTL → free the reserved-id
      // slot on the previous owner so its count reflects the loss (#1/#3).
      if (verdict === 'reclaim' && reservation && reservation.ownerSlug !== slug) {
        await this.accountRpc('/release-id', { tunnelId }, reservation.ownerSlug);
      }

      // Seed the rate snapshot + quota level so headers work from the first
      // request and we don't re-announce the level the client already sees.
      this.rate = auth.rate ?? null;
      this.lastQuotaLevel = auth.rate?.level ?? null;
      const url = `https://${tunnelId}.${this.env.TUNNEL_DOMAIN}`;
      sendFrame(ws, {
        type: 'registered',
        tunnelId,
        url,
        account: auth.rate ? { slug, day: auth.rate.day, month: auth.rate.month, level: auth.rate.level } : undefined,
      });
      return;
    }

    if (type === 'response') {
      const pending = this.pendingHttp.get(msg.reqId as string);
      if (!pending) return;
      clearTimeout(pending.timer);
      this.pendingHttp.delete(msg.reqId as string);
      const headers = buildResponseHeaders(
        (msg.headers as Record<string, string>) || {},
        pending.request,
        pending.bootstrapCookie,
        this.headerRules
      );
      for (const [k, v] of Object.entries(pending.rate)) headers.set(k, v);
      // A malformed body must resolve the request (502), not throw out of the
      // hibernation handler and leave it hung (timer already cleared above).
      let body: Uint8Array | null;
      try {
        body = msg.body ? b64decode(msg.body as string) : null;
      } catch {
        this.finishInspect(msg.reqId as string, 502, null);
        pending.resolve(new Response('Malformed tunnel response', { status: 502, headers }));
        return;
      }
      this.finishInspect(msg.reqId as string, (msg.status as number) || 200, body ? body.length : 0);
      // Workers strip content-encoding from a constructed Response and assume the
      // body is decoded; a compressed upstream body then ships headerless and the
      // consumer reads gzip bytes as text. encodeBody manual passes both through.
      pending.resolve(new Response(body, { status: (msg.status as number) || 200, headers, ...(headers.has('content-encoding') ? { encodeBody: 'manual' as const } : {}) } as ResponseInit));
      return;
    }

    if (type === 'response-start') {
      const pending = this.pendingHttp.get(msg.reqId as string);
      if (!pending) return;
      clearTimeout(pending.timer);
      this.pendingHttp.delete(msg.reqId as string);
      const reqId = msg.reqId as string;
      // Streamed: record status + latency-to-first-byte now; body size is unknown
      // (chunks stream out), so leave bytes null.
      this.finishInspect(reqId, (msg.status as number) || 200, null);
      const headers = buildResponseHeaders(
        (msg.headers as Record<string, string>) || {},
        pending.request,
        pending.bootstrapCookie,
        this.headerRules
      );
      for (const [k, v] of Object.entries(pending.rate)) headers.set(k, v);
      const status = (msg.status as number) || 200;
      // Fetch forbids a body for these statuses. Constructing a Response with a
      // ReadableStream throws after the pending entry has been removed, leaving
      // the visitor request unresolved forever. HEAD is bodyless by contract too.
      if (pending.request.method === 'HEAD' || status === 204 || status === 205 || status === 304) {
        pending.resolve(new Response(null, { status, headers }));
        return;
      }
      const self = this;
      const readable = new ReadableStream<Uint8Array>({
        start(controller) {
          self.streaming.set(reqId, { controller, idle: self.armStreamIdle(reqId) });
        },
        cancel() {
          const s = self.streaming.get(reqId);
          if (s) clearTimeout(s.idle);
          self.streaming.delete(reqId);
          const ctl = self.ctl();
          if (ctl) {
            try {
              sendFrame(ctl, { type: 'request-abort', reqId });
            } catch {
              /* control gone */
            }
          }
        },
      });
      pending.resolve(new Response(readable, { status, headers, ...(headers.has('content-encoding') ? { encodeBody: 'manual' as const } : {}) } as ResponseInit));
      return;
    }

    if (type === 'response-chunk') {
      const s = this.streaming.get(msg.reqId as string);
      if (s) {
        try {
          s.controller.enqueue(b64decode(msg.data as string));
          clearTimeout(s.idle);
          s.idle = this.armStreamIdle(msg.reqId as string);
        } catch {
          clearTimeout(s.idle);
          this.streaming.delete(msg.reqId as string);
        }
      }
      return;
    }

    if (type === 'response-end') {
      const s = this.streaming.get(msg.reqId as string);
      if (s) {
        clearTimeout(s.idle);
        this.streaming.delete(msg.reqId as string);
        try {
          s.controller.close();
        } catch {
          /* already closed */
        }
      }
      return;
    }

    if (type === 'ws-ready') {
      const p = this.pendingUpgrades.get(msg.connId as string);
      if (p) {
        clearTimeout(p.timer);
        this.pendingUpgrades.delete(msg.connId as string);
        p.resolve();
      }
      return;
    }

    if (type === 'ws-error') {
      const p = this.pendingUpgrades.get(msg.connId as string);
      if (p) {
        clearTimeout(p.timer);
        this.pendingUpgrades.delete(msg.connId as string);
        p.reject(new Error((msg.error as string) || 'Tunnel error'));
      }
      return;
    }

    if (type === 'ws-message') {
      // control → browser
      const arr = this.ctx.getWebSockets(`c:${msg.connId}`);
      const browser = arr.length ? (arr[0] as WebSocket) : null;
      if (browser) {
        try {
          const bytes = b64decode(msg.data as string);
          browser.send(msg.binary ? bytes : new TextDecoder().decode(bytes));
        } catch {
          /* malformed frame — drop it, keep the relay alive */
        }
      }
      return;
    }

    if (type === 'ws-close') {
      const arr = this.ctx.getWebSockets(`c:${msg.connId}`);
      const browser = arr.length ? (arr[0] as WebSocket) : null;
      if (browser) {
        const raw = msg.code as number | undefined;
        const code = raw && raw >= 1000 && raw <= 4999 && raw !== 1005 && raw !== 1006 ? raw : 1000;
        try {
          browser.close(code, truncateReason(msg.reason));
        } catch {
          /* ignore */
        }
      }
      return;
    }
  }
}

x-reference.routing:
/**
 * Worker entry — routes every request to the Durable Object for its tunnelId.
 *
 * - Control channel: `…/ws?id=<tunnelId>` (WS upgrade) → DO(idFromName(id)).
 * - Data (HTTP or browser WS): `Host: <tunnelId>.<domain>` → DO(idFromName(tunnelId)).
 * - Apex (no subdomain): /api/status and the /__volter_auth cookie bootstrap.
 *
 * State is sharded per tunnel by construction: both the client's control socket
 * and inbound requests for a tunnel deterministically map to the same DO.
 */
import { type Env, getTunnelIdFromHost, handleCookieBootstrap } from './auth';
import { TunnelDO } from './tunnel-do';
import { AccountDO } from './account-do';
import { RegistryDO } from './registry-do';
import { docsPage, fontResponse, htmlResponse, landingPage } from './pages';

export { TunnelDO, AccountDO, RegistryDO };

function routeToDO(env: Env, name: string, request: Request): Promise<Response> {
  const id = env.TUNNEL.idFromName(name);
  return env.TUNNEL.get(id).fetch(request);
}

/** Subdomain labels that are NOT tunnels — they serve the apex front door /
 *  management plane instead (so `www.<domain>` shows the landing page rather
 *  than being a tunnel named "www", and nobody can reserve a tunnel that shadows
 *  them). Override via RESERVED_HOSTS (comma-separated); default `www`. */
function isReservedHost(env: Env, label: string): boolean {
  const raw = (env.RESERVED_HOSTS ?? 'www').toLowerCase();
  return raw
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .includes(label.toLowerCase());
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // Control channel — host-independent; the client names its DO via ?id=.
    if (url.pathname === '/ws') {
      const id = url.searchParams.get('id');
      if (!id) return new Response('missing tunnel id', { status: 400 });
      return routeToDO(env, id, request);
    }

    // Direct tunnel addressing for hosts without a per-tunnel subdomain — e.g.
    // *.workers.dev (Cloudflare rejects a foreign Host) or local testing.
    // `?__tunnel=<id>` is stripped before the request is forwarded downstream.
    // Gated to direct hosts only: on the production wildcard domain, tunnels must
    // be reached by their own subdomain so per-tunnel cookie/host isolation holds.
    const host = request.headers.get('host') || '';
    const isDirectHost =
      host.endsWith('.workers.dev') ||
      host.startsWith('127.0.0.1') ||
      host.startsWith('localhost') ||
      host.startsWith('0.0.0.0');
    const override = url.searchParams.get('__tunnel');
    if (override && isDirectHost) return routeToDO(env, override, request);

    const tunnelId = getTunnelIdFromHost(request.headers.get('host'), env.TUNNEL_DOMAIN);

    // On a tunnel subdomain EVERYTHING forwards to the tunnel — paths like
    // /admin, /signup, /report are management routes only on the apex, never on a
    // tunnel host (otherwise a tunneled app's own /signup page would be hijacked).
    // Reserved labels (e.g. `www`) are NOT tunnels — they fall through to the apex
    // front door below so `www.<domain>` serves the landing page.
    if (tunnelId && !isReservedHost(env, tunnelId)) return routeToDO(env, tunnelId, request);

    // Apex (no subdomain) or a reserved host: management plane (admin), self-serve
    // signup (#2,
    // unauthenticated — identity via GitHub), and abuse reports (#3). All share
    // the single RegistryDO.
    if (
      url.pathname === '/admin' ||
      url.pathname.startsWith('/admin/') ||
      url.pathname === '/signup' ||
      url.pathname.startsWith('/signup/') ||
      url.pathname === '/waitlist' ||
      url.pathname === '/report' ||
      url.pathname === '/me' ||
      url.pathname.startsWith('/me/')
    ) {
      const id = env.REGISTRY.idFromName('registry');
      return env.REGISTRY.get(id).fetch(request);
    }
    if (url.pathname.startsWith('/__volter_auth')) {
      return handleCookieBootstrap(request, url, env);
    }
    if (url.pathname === '/api/status') {
      return Response.json({ ok: true, relay: 'cloudflare-do' });
    }
    // Public front door (apex only): marketing landing + waitlist form, and docs.
    if (request.method === 'GET' && (url.pathname === '/' || url.pathname === '')) {
      return htmlResponse(landingPage(env.TUNNEL_DOMAIN));
    }
    if (request.method === 'GET' && (url.pathname === '/docs' || url.pathname === '/docs/')) {
      return htmlResponse(docsPage(env.TUNNEL_DOMAIN));
    }
    if (request.method === 'GET' && url.pathname.startsWith('/fonts/')) {
      const font = fontResponse(url.pathname.slice('/fonts/'.length));
      if (font) return font;
    }
    return new Response('volter-tunnel (cloudflare)', { status: 200 });
  },
};

x-reference.credentials:
/**
 * Metering primitives shared across the Worker, RegistryDO, AccountDO and TunnelDO.
 *
 * Tokens are opaque, prefixed, and carry the account slug so the data plane can
 * route straight to the strongly-consistent AccountDO without a global index —
 * the same trick Cloudflare Tunnel's own connector token uses (it embeds the
 * account + tunnel id). Only the SHA-256 of a token is ever persisted; the
 * plaintext is shown once at creation.
 *
 *   vtr_<rand>            root token   (global; manages accounts + limits)
 *   vts_<slug>_<rand>     service token (per account; mints/revokes api tokens)
 *   vta_<slug>_<rand>     api token     (per account; the "tunnel secret")
 *
 * "Credits" are the single blended spend unit. requests / ws-upgrades / bytes /
 * tunnel-seconds each convert to credits via CREDIT_WEIGHTS, and daily+monthly
 * limits are enforced on credits. Defaults charge per request/upgrade only —
 * bytes are free egress on Workers, and tunnel-seconds are gated by the
 * concurrent-tunnel cap rather than priced — but every weight is tunable.
 */

export type TokenKind = 'root' | 'service' | 'api';

export interface ParsedToken {
  kind: TokenKind;
  /** Account slug — present for service/api tokens, undefined for root. */
  slug?: string;
}

const SLUG_RE = /^[a-z0-9][a-z0-9-]{1,62}$/;

/** Whether a string is a valid account slug (DNS-label-ish, no underscores). */
export function isValidSlug(slug: string): boolean {
  return SLUG_RE.test(slug);
}

/**
 * Parse a token string into its kind + slug. Returns null for anything that
 * doesn't match the `vt*` grammar (e.g. a legacy shared secret). Underscore is
 * the field separator and never appears inside a slug or random part, so the
 * split is unambiguous.
 */
export function parseToken(token: string): ParsedToken | null {
  if (typeof token !== 'string' || token.length < 8) return null;
  const parts = token.split('_');
  if (parts[0] === 'vtr') {
    return parts.length === 2 && parts[1] ? { kind: 'root' } : null;
  }
  if (parts[0] === 'vts' || parts[0] === 'vta') {
    if (parts.length !== 3) return null;
    const slug = parts[1]!;
    if (!isValidSlug(slug) || !parts[2]) return null;
    return { kind: parts[0] === 'vts' ? 'service' : 'api', slug };
  }
  return null;
}

const BASE62 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

/** Cryptographically-random base62 string of `len` chars. */
export function randomBase62(len = 40): string {
  const bytes = new Uint8Array(len);
  crypto.getRandomValues(bytes);
  let s = '';
  for (let i = 0; i < len; i++) s += BASE62[bytes[i]! % 62];
  return s;
}

/** Mint a fresh token of the given kind (root tokens carry no slug). */
export function mintToken(kind: TokenKind, slug?: string): string {
  if (kind === 'root') return `vtr_${randomBase62()}`;
  const prefix = kind === 'service' ? 'vts' : 'vta';
  return `${prefix}_${slug}_${randomBase62()}`;
}

/** SHA-256 hex digest — the only form of a token we persist. */
export async function hashToken(token: string): Promise<string> {
  const data = new TextEncoder().encode(token);
  const digest = await crypto.subtle.digest('SHA-256', data);
  const bytes = new Uint8Array(digest);
  let hex = '';
  for (let i = 0; i < bytes.length; i++) hex += bytes[i]!.toString(16).padStart(2, '0');
  return hex;
}

/** Constant-time hex-string compare (both are fixed-length SHA-256 hex). */
export function safeEqualHex(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}

/** Last 4 chars of a token — stored for display ("…aB3x") without the secret. */
export function last4(token: string): string {
  return token.slice(-4);
}

// ── credit accounting ────────────────────────────────────────────────────────

export interface CreditWeights {
  request: number;
  wsUpgrade: number;
  /** Per relayed DO message (response chunk or WebSocket frame). */
  message: number;
  byte: number;
  second: number;
}

/**
 * Credits are denominated in **ops** — the universal Cloudflare billable unit.
 * Every event that wakes/charges the relay's Durable Object counts as 1 op:
 * an HTTP request, a WS upgrade, and each relayed message (a streamed response
 * chunk or a WebSocket frame). Metering messages — not just the opening request
 * — is what makes a dollar cap actually hold for streaming/WS-heavy tunnels.
 *
 * Dollars = credits × COST_PER_OP_USD. Bytes/seconds are 0 (egress is free on
 * Workers; idle duration is ~0 under hibernation and bounded by the concurrency
 * cap), but the message weight captures the per-frame DO cost that does bill.
 */
export const CREDIT_WEIGHTS: CreditWeights = {
  request: 1,
  wsUpgrade: 1,
  message: 1,
  byte: 0,
  second: 0,
};

/**
 * Conservative estimate of the Cloudflare cost of one op, in USD. An op bills
 * roughly: 1 Worker request + 1–2 DO requests + a slice of DO active duration,
 * plus amortized unmetered overhead (the AccountDO lease/authorize/close RPCs,
 * and billed-but-free paths like OPTIONS/502/429). Real Worker+DO request prices
 * are ~$0.15–0.45/M, so $1/M carries ~2–3× headroom over the direct request cost
 * to absorb that overhead. This is the ONLY money↔ops knob — RAISE it (and the
 * dollar caps stay honest, op-limits auto-shrink) once a real CF invoice lets you
 * calibrate; lower it only if you're confident it over-charges.
 */
export const COST_PER_OP_USD = 0.000001;

/** Dollar amount → integer op-credits (for setting limits in money). */
export function usdToCredits(usd: number): number {
  return Math.round(usd / COST_PER_OP_USD);
}
/** Op-credits → dollars, rounded to cents (for display). */
export function creditsToUsd(credits: number): number {
  return Math.round(credits * COST_PER_OP_USD * 100) / 100;
}

export interface UsageDelta {
  requests?: number;
  wsUpgrades?: number;
  messages?: number;
  bytes?: number;
  seconds?: number;
}

/** Convert a raw usage delta into integer credits using the given weights. */
export function toCredits(d: UsageDelta, w: CreditWeights = CREDIT_WEIGHTS): number {
  const raw =
    (d.requests ?? 0) * w.request +
    (d.wsUpgrades ?? 0) * w.wsUpgrade +
    (d.messages ?? 0) * w.message +
    (d.bytes ?? 0) * w.byte +
    (d.seconds ?? 0) * w.second;
  return Math.ceil(raw);
}

// ── period keys (UTC) ────────────────────────────────────────────────────────

/** UTC day bucket, e.g. "2026-06-23". */
export function dayKey(now: Date): string {
  return now.toISOString().slice(0, 10);
}
/** UTC month bucket, e.g. "2026-06". */
export function monthKey(now: Date): string {
  return now.toISOString().slice(0, 7);
}

x-reference.auth:
/**
 * Auth + header helpers for the Cloudflare tunnel relay.
 *
 * Implements the JWT/cookie/CORS/CSP logic on the Fetch API + `jose` (WebCrypto-based; `jsonwebtoken` does not run on Workers).
 */
import { type JWTPayload, jwtVerify } from 'jose';
import type { MeteringEnv } from './metering-types';

export interface Env extends MeteringEnv {
  TUNNEL: DurableObjectNamespace;
  TUNNEL_DOMAIN: string;
  TUNNEL_SECRET: string;
  JWT_SECRET: string;
  /** When 'true', a data-plane JWT MUST carry a `tid` claim matching the tunnel
   *  (full per-tunnel isolation). Default: a JWT with a `tid` is still bound to
   *  that tunnel, but a JWT without one is accepted on any tunnel (shared SSO). */
  REQUIRE_TID?: string;
  /** Idle days before a reserved tunnelId may be reclaimed by another account on
   *  contention (DECISIONS D5). Default 60. */
  RESERVATION_IDLE_TTL_DAYS?: string;
  /** Optional JSON response-header rewrite rules, applied on top of the built-in
   *  iframe strip: `{"set":{"x-foo":"bar"},"remove":["x-baz"]}`. */
  RESPONSE_HEADER_RULES?: string;
  /** Per-tunnel request-rate burst limit (#4): sustained requests/sec. 0/unset =
   *  disabled. The daily/monthly credit caps remain the primary fair-use limit. */
  BURST_RPS?: string;
  /** Token-bucket capacity for BURST_RPS (max instantaneous burst). Default 2×RPS. */
  BURST_SIZE?: string;
  /** Inspector replay + persisted history (#10): 'true'/'1' captures request
   *  detail to DO storage (survives hibernation) and enables /__volter_replay. */
  INSPECT_REPLAY?: string;
  /** Max captured requests retained for replay (default 50). */
  INSPECT_MAX?: string;
  /** Max captured request-body bytes stored per request (default 65536). */
  INSPECT_BODY_MAX?: string;
  /** Comma-separated subdomain labels that serve the apex front door / management
   *  plane instead of being tunnels (e.g. `www`). Default: `www`. */
  RESERVED_HOSTS?: string;
}

/**
 * Extract the tunnelId from a Host header. Port-tolerant.
 *
 * `<id>.<domain>` → `<id>`, and — wildcard support (P1 #9) — `*.<id>.<domain>`
 * also → `<id>`: every label under a reserved id routes to that id's tunnel.
 * Tunnel ids are single DNS labels (no dots), so the id is always the label
 * adjacent to the base domain (the rightmost label of the subdomain portion);
 * the leading labels are the wildcard prefix, left intact on the forwarded Host
 * so the tunneled app can sub-route on them.
 */
export function getTunnelIdFromHost(host: string | null, domain: string): string | null {
  if (!host) return null;
  const hostname = host.split(':')[0];
  const suffix = '.' + domain;
  if (hostname.endsWith(suffix)) {
    const sub = hostname.slice(0, -suffix.length);
    return sub.slice(sub.lastIndexOf('.') + 1) || null;
  }
  return null;
}

export function parseCookies(cookieHeader: string | null): Map<string, string> {
  const cookies = new Map<string, string>();
  if (!cookieHeader) return cookies;
  for (const pair of cookieHeader.split(';')) {
    const idx = pair.indexOf('=');
    if (idx < 0) continue;
    cookies.set(pair.slice(0, idx).trim(), pair.slice(idx + 1).trim());
  }
  return cookies;
}

/** Verify a JWT signature; return its payload (or null on failure). */
async function verifyToken(token: string, secret: string): Promise<JWTPayload | null> {
  try {
    const { payload } = await jwtVerify(token, new TextEncoder().encode(secret), { algorithms: ['HS256'] });
    return payload;
  } catch {
    return null;
  }
}

/** Boolean wrapper (the cookie-bootstrap path doesn't need the payload). */
async function verify(token: string, secret: string): Promise<boolean> {
  return (await verifyToken(token, secret)) !== null;
}

/** Per-tunnel binding check. A token with a `tid` claim is bound to that tunnel;
 *  a token without one is accepted on any tunnel unless `requireTid`. */
function tidOk(payload: JWTPayload, tunnelId: string | undefined, requireTid: boolean): boolean {
  const tid = typeof payload.tid === 'string' ? payload.tid : undefined;
  if (tid !== undefined) return !tunnelId || tid === tunnelId;
  return !requireTid;
}

export interface AuthResult {
  token: string;
  source: 'header' | 'query' | 'cookie';
}

export interface AuthOpts {
  /** Tunnel this request is for — a `tid`-bound token must match it. */
  tunnelId?: string;
  /** Reject tokens that carry no `tid` claim (full per-tunnel isolation). */
  requireTid?: boolean;
}

/** Validate auth from an HTTP request: Bearer header → ?__volter_token= → __volter_auth cookie. */
export async function validateAuth(
  request: Request,
  url: URL,
  jwtSecret: string,
  opts: AuthOpts = {}
): Promise<AuthResult | null> {
  if (!jwtSecret) return null;
  const ok = (p: JWTPayload | null) => !!p && tidOk(p, opts.tunnelId, !!opts.requireTid);

  const authHeader = request.headers.get('authorization');
  if (authHeader?.startsWith('Bearer ')) {
    const token = authHeader.slice(7);
    return ok(await verifyToken(token, jwtSecret)) ? { token, source: 'header' } : null;
  }

  const queryToken = url.searchParams.get('__volter_token');
  if (queryToken) {
    return ok(await verifyToken(queryToken, jwtSecret)) ? { token: queryToken, source: 'query' } : null;
  }

  const cookieToken = parseCookies(request.headers.get('cookie')).get('__volter_auth');
  if (cookieToken) {
    return ok(await verifyToken(cookieToken, jwtSecret)) ? { token: cookieToken, source: 'cookie' } : null;
  }

  return null;
}

/** Validate auth for a WebSocket upgrade: ?__volter_token= query param → cookie. */
export async function validateWsAuth(
  request: Request,
  url: URL,
  jwtSecret: string,
  opts: AuthOpts = {}
): Promise<boolean> {
  if (!jwtSecret) return false;
  const ok = (p: JWTPayload | null) => !!p && tidOk(p, opts.tunnelId, !!opts.requireTid);
  const queryToken = url.searchParams.get('__volter_token');
  if (queryToken) return ok(await verifyToken(queryToken, jwtSecret));
  const cookieToken = parseCookies(request.headers.get('cookie')).get('__volter_auth');
  if (cookieToken) return ok(await verifyToken(cookieToken, jwtSecret));
  return false;
}

/** Remove `?__volter_token=` from a path+query string (don't leak the token downstream). */
export function stripTokenParam(pathWithQuery: string): string {
  try {
    const u = new URL(pathWithQuery, 'http://placeholder');
    u.searchParams.delete('__volter_token');
    u.searchParams.delete('__tunnel');
    const search = u.searchParams.toString();
    return u.pathname + (search ? '?' + search : '');
  } catch {
    return pathWithQuery;
  }
}

/** Strip the __volter_auth cookie from a headers object before forwarding downstream. */
export function stripAuthCookie(headers: Record<string, string>): Record<string, string> {
  const cookie = headers.cookie;
  if (!cookie) return headers;
  const cleaned = cookie
    .split(';')
    .filter((pair) => pair.trim().split('=')[0]?.trim() !== '__volter_auth')
    .join(';')
    .trim();
  const result = { ...headers };
  if (cleaned) result.cookie = cleaned;
  else delete result.cookie;
  return result;
}

/** CORS headers for a tunneled response (all tunnel traffic is cross-origin).
 *
 *  The relay answers preflight itself (it never forwards OPTIONS to the
 *  origin app), so the allow-headers grant must cover whatever custom headers
 *  the tunneled app's clients send — which the relay cannot know in advance.
 *  Reflect the browser's Access-Control-Request-Headers verbatim: the browser
 *  lists exactly the headers the real request will carry, and a wildcard is
 *  not an option because allow-credentials is true (spec ignores `*` there).
 *  The fixed list remains as a fallback for non-preflight responses, which
 *  carry no request-headers hint. */
export function corsHeaders(request: Request): Record<string, string> {
  const origin = request.headers.get('origin');
  if (!origin) return {};
  const requested = request.headers.get('access-control-request-headers');
  return {
    'access-control-allow-origin': origin,
    'access-control-allow-methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
    'access-control-allow-headers': requested || 'Content-Type, Authorization, X-Sandbox-Id',
    'access-control-allow-credentials': 'true',
  };
}

/** Operator-configurable response-header rewrite rules, applied on top of the
 *  built-in iframe strip. Keys are lower-cased to match Workers' header casing. */
export interface HeaderRules {
  /** Force-set these response headers (override whatever downstream returned). */
  set?: Record<string, string>;
  /** Remove these response headers. */
  remove?: string[];
}

/** Parse RESPONSE_HEADER_RULES (JSON) into HeaderRules. Tolerant: malformed JSON
 *  or unexpected shape yields no extra rules — the built-in iframe strip always
 *  still applies, so a bad config can never un-strip frame-ancestors. */
export function parseHeaderRules(raw: string | undefined): HeaderRules {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as { set?: unknown; remove?: unknown };
    const rules: HeaderRules = {};
    if (parsed && typeof parsed.set === 'object' && parsed.set) {
      const set: Record<string, string> = {};
      for (const [k, v] of Object.entries(parsed.set as Record<string, unknown>)) {
        if (typeof v === 'string') set[k.toLowerCase()] = v;
      }
      if (Object.keys(set).length) rules.set = set;
    }
    if (Array.isArray(parsed.remove)) {
      const remove = (parsed.remove as unknown[])
        .filter((x): x is string => typeof x === 'string')
        .map((x) => x.toLowerCase());
      if (remove.length) rules.remove = remove;
    }
    return rules;
  } catch {
    return {};
  }
}

/**
 * Build the downstream response headers: drop hop-by-hop + downstream CORS,
 * strip CSP frame-ancestors / X-Frame-Options (the built-in iframe embedding —
 * always on), apply any operator-configured `rules`, then re-apply our CORS +
 * cookie.
 */
export function buildResponseHeaders(
  downstream: Record<string, string>,
  request: Request,
  bootstrapCookie: string | null,
  rules?: HeaderRules
): Headers {
  const headers = { ...downstream };
  for (const k of [
    'transfer-encoding',
    'connection',
    'access-control-allow-origin',
    'access-control-allow-methods',
    'access-control-allow-headers',
    'access-control-allow-credentials',
  ]) {
    delete headers[k];
  }

  for (const key of ['content-security-policy', 'content-security-policy-report-only']) {
    if (headers[key]) {
      headers[key] = headers[key]
        .split(';')
        .filter((d) => !d.trim().startsWith('frame-ancestors'))
        .join(';')
        .trim();
      if (!headers[key]) delete headers[key];
    }
  }
  delete headers['x-frame-options'];

  // Operator-configured rewrite rules, on top of the built-in strip. Remove
  // before set so a rule can both clear and re-set the same header deliberately.
  if (rules?.remove) for (const k of rules.remove) delete headers[k];
  if (rules?.set) for (const [k, v] of Object.entries(rules.set)) headers[k] = v;

  // Tunnel responses are dynamic and frequently authenticated. Make caching an
  // explicit opt-in: only a downstream response that clearly says `public` may
  // be stored. This defeats zone/cache-rule mistakes that key an authenticated
  // `/api` response only by path while preserving immutable hashed assets.
  const cacheControl = (headers['cache-control'] ?? '').toLowerCase();
  const explicitlyPublic =
    /(?:^|,)\s*public(?:\s|,|$)/.test(cacheControl) &&
    !/(?:^|,)\s*(?:private|no-store|no-cache)(?:\s|,|=|$)/.test(cacheControl);
  const pathname = new URL(request.url).pathname;
  if (!explicitlyPublic || pathname === '/api' || pathname.startsWith('/api/')) {
    headers['cache-control'] = 'private, no-store, max-age=0';
    // Cloudflare-CDN-Cache-Control is the provider-specific override; the
    // standards-track CDN-Cache-Control protects other relay deployments too.
    headers['cloudflare-cdn-cache-control'] = 'no-store';
    headers['cdn-cache-control'] = 'no-store';
    const vary = new Set(
      (headers.vary ?? '')
        .split(',')
        .map((v) => v.trim())
        .filter(Boolean)
    );
    vary.add('Cookie');
    vary.add('Authorization');
    headers.vary = [...vary].join(', ');
  }

  const out = new Headers();
  for (const [k, v] of Object.entries(headers)) {
    if (v != null) out.set(k, v);
  }
  for (const [k, v] of Object.entries(corsHeaders(request))) out.set(k, v);
  if (bootstrapCookie) out.append('set-cookie', bootstrapCookie);
  return out;
}

/** Build the auth cookie. `cookieDomain` is the host the cookie is scoped to —
 *  pass `<tunnelId>.<domain>` to isolate one tunnel (the leading dot still covers
 *  its `*.<tunnelId>.<domain>` wildcard subdomains, but NOT other tunnels), or the
 *  bare apex `<domain>` for the legacy shared-SSO scope. */
export function cookieFor(token: string, cookieDomain: string): string {
  return `__volter_auth=${token}; Domain=.${cookieDomain}; HttpOnly; SameSite=None; Secure; Path=/; Max-Age=3600`;
}

/** GET /__volter_auth?__volter_token=<jwt> → set the cross-iframe auth cookie. */
export async function handleCookieBootstrap(request: Request, url: URL, env: Env): Promise<Response> {
  const cors = corsHeaders(request);
  if (request.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers: cors });
  }
  const token = url.searchParams.get('__volter_token');
  if (!token || !env.JWT_SECRET) {
    return Response.json({ error: 'Missing token parameter' }, { status: 400, headers: cors });
  }
  const payload = await verifyToken(token, env.JWT_SECRET);
  if (!payload) {
    return Response.json({ error: 'Invalid token' }, { status: 401, headers: cors });
  }
  // A tunnel-bound token scopes its cookie to that tunnel; an unbound token keeps
  // the apex scope (legacy shared SSO).
  const tid = typeof payload.tid === 'string' ? payload.tid : undefined;
  const cookieDomain = tid ? `${tid}.${env.TUNNEL_DOMAIN}` : env.TUNNEL_DOMAIN;
  return Response.json(
    { ok: true },
    { status: 200, headers: { ...cors, 'set-cookie': cookieFor(token, cookieDomain) } }
  );
}

x-reference.domain:
{
  "$schema": "node_modules/wrangler/config-schema.json",
  "name": "volter-tunnel",
  "main": "src/worker.ts",
  "compatibility_date": "2026-06-16",
  "observability": { "enabled": true },

  "durable_objects": {
    "bindings": [
      { "name": "TUNNEL", "class_name": "TunnelDO" },
      { "name": "ACCOUNTS", "class_name": "AccountDO" },
      { "name": "REGISTRY", "class_name": "RegistryDO" }
    ]
  },
  "migrations": [
    { "tag": "v1", "new_sqlite_classes": ["TunnelDO"] },
    { "tag": "v2", "new_sqlite_classes": ["AccountDO", "RegistryDO"] }
  ],

  // Durable per-account usage time-series. Requires enabling Analytics Engine on
  // the account first (dash.cloudflare.com → Workers → Analytics Engine); then
  // uncomment this binding and redeploy. The recordAE() calls are no-ops until then.
  // "analytics_engine_datasets": [{ "binding": "USAGE_AE", "dataset": "tunnel_usage" }],

  // Public base domain for tunnel URLs. Tunnel URLs are {tunnelId}.<this>.
  // Use a 1-level wildcard zone so free Universal SSL covers *.<domain>.
  // Override per-env / via `--var` in tests.
  //
  // Metering vars (non-secret) — global ceiling = Σ(account limits) cap, and the
  // built-in internal account's defaults. ROOT_TOKEN is a secret (wrangler secret
  // put ROOT_TOKEN). Credits are charged per request/ws-upgrade by default.
  // Limits are denominated in MONEY. Credits are ops (≈ CF billable events:
  // requests, ws-upgrades, relayed messages) and 1 op = COST_PER_OP_USD
  // (~$1/million, conservative). So these op-limits are a hard dollar cap:
  //   INTERNAL_DAY_LIMIT  10,000,000 ops  = $10/day
  //   INTERNAL_MONTH_LIMIT 100,000,000 ops = $100/month
  // Every account (internal included) is gated the same way. Create/raise with
  // dollars directly: POST /admin/accounts { dayUsd: 10, monthUsd: 100 }.
  // Global = Σ(account limits) ceiling.
  "vars": {
    "TUNNEL_DOMAIN": "voltertest.xyz",
    // Per-tunnel viewer isolation. The full chain is BUILT + DEPLOYED (gateway
    // mints tid tokens via /api/tunnel/token; frontend sends them; cookie scoped
    // to .<tunnelId>.<domain>). Set "true" to ENFORCE (reject tokens lacking a
    // matching `tid`) — do that ONLY after a signed-in browser smoke confirms a
    // dev preview still loads (the cross-site iframe-cookie behavior is the one
    // thing unit tests can't cover). Off = safe: tid tokens flow but aren't
    // required. Only affects authRequired:true tunnels.
    "REQUIRE_TID": "false",
    "INTERNAL_ACCOUNT": "volter-internal",
    "INTERNAL_DAY_LIMIT": "10000000",
    "INTERNAL_MONTH_LIMIT": "100000000",
    "INTERNAL_CONCURRENT": "1000",
    "GLOBAL_DAY_LIMIT": "1000000000",
    "GLOBAL_MONTH_LIMIT": "10000000000",
    "DEFAULT_CONCURRENT": "100",
    "DEFAULT_LEASE_CHUNK": "50",

    // ── Free-tier signup + reservation policy (#2/#3) — confirm vs DECISIONS D6.
    // NOTE: SIGNUP_DAY/MONTH_LIMIT are op-credits (~$1/million). The code default
    // is only 1000 (≈$0.001) — far too small — so set real values here.
    "SIGNUP_DAY_LIMIT": "1000000", //  ≈ $1/day per free account
    "SIGNUP_MONTH_LIMIT": "10000000", //  ≈ $10/month per free account
    "DEFAULT_RESERVED_MAX": "3", //  reserved tunnel ids per free account
    "RESERVATION_IDLE_TTL_DAYS": "60", //  idle days before a reserved id is reclaimable

    // ── Fair-use request burst (#4). Generous defaults: 50 req/s/tunnel sustained,
    // 500 instantaneous (covers heavy page loads / interactive dev), so only real
    // floods are throttled. The daily/monthly credit caps remain the primary limit.
    "BURST_RPS": "50",
    "BURST_SIZE": "500",

    // ── Cost-DoS guard on the unauthenticated public surface (/signup/*, /report).
    "SIGNUP_RPS": "5"

    // Optional (unset = off):
    //   SIGNUP_ALLOWED_USERS — allowlist mode (comma-separated GitHub logins, or the verified email of a Volter identity without GitHub).
    //     Signup FAILS CLOSED when unset/empty; set SIGNUP_OPEN=true to allow
    //     everyone. Set via `wrangler secret put` (keep logins out of the repo).
    //   SIGNUP_OPEN=true     — open signup to everyone (only when no allowlist).
    //   INSPECT_REPLAY=true  — persisted inspector history + /__volter_replay.
    //   GITHUB_API_BASE      — override the GitHub API (default api.github.com).
  },

  // workers_dev is OFF: all ingress must go through the zone routes below so the
  // WAF rate-limit rule covers the unauthenticated surface (/signup,/report,
  // /waitlist). The control channel (/ws) is host-independent and served by the
  // apex route; *.workers.dev is not needed in prod (localhost covers __tunnel
  // testing). Leaving it on would expose an un-WAF'd <name>.<acct>.workers.dev.
  "workers_dev": false,
  "routes": [
    { "pattern": "*.voltertest.xyz/*", "zone_name": "voltertest.xyz" },
    // Bare apex serves the public front door (landing/docs/management). The apex
    // DNS is already proxied; the wildcard cert above doesn't match the apex, so
    // it needs its own route. Universal SSL covers the apex hostname.
    { "pattern": "voltertest.xyz/*", "zone_name": "voltertest.xyz" }
  ]

  // Secrets (set via `wrangler secret put` in prod, `.dev.vars` locally):
  //   TUNNEL_SECRET, JWT_SECRET, ROOT_TOKEN
}
